//! Independent source-key parity and stage-boundary checks for offline factories.
//!
//! Factory synthesis does not prepare an operation or authenticate a catalog.
//! These checks compare its complete generated descriptor/VK with keys already
//! generated by the independent, genuinely proved reference source.

use iroha_kagemusha_proof::{
    a_relation::{
        context::ContextPlan,
        native::artifact::KeyArtifact,
        split::{WCircuit, WKey},
    },
    omega::OmegaPlan,
};
use iroha_pasta::{Ep, Eq, Fp};
use iroha_plonk::{
    DescriptorBinding, VerifyingKey,
    cs::InstanceType,
    frontend::Circuit,
    keys::{KeygenConfigV2, keygen_vk_with_binding_v2},
    pcs::ipa::PinnedParams,
};

/// Compare each exact source identity without obtaining a monetary witness or PK.
pub fn assert_factories<A: Circuit<Fp>, E: core::fmt::Debug>(
    context: &ContextPlan,
    pallas: &PinnedParams<Ep>,
    vesta: &PinnedParams<Eq>,
    a: &[KeyArtifact<Eq>],
    w: &[KeyArtifact<Ep>],
    source: impl Fn(usize, Option<WKey>) -> Result<A, E>,
    wrapper: impl Fn(usize, &DescriptorBinding, &VerifyingKey<Eq>) -> Result<WCircuit, E>,
) {
    assert_eq!(a.len(), context.stage_count());
    assert_eq!(w.len() + 1, a.len());
    let mut a_config = KeygenConfigV2::pipa_r(vec![InstanceType::Bounded]);
    a_config.compress_selectors = false;
    let mut w_config = KeygenConfigV2::pipa_r(OmegaPlan::instance_types().to_vec());
    w_config.compress_selectors = false;
    let mut previous = None;
    for (stage, artifact) in a.iter().enumerate() {
        let candidate = source(stage, previous.clone()).unwrap();
        let (binding, key) = keygen_vk_with_binding_v2(vesta, &candidate, &a_config).unwrap();
        assert_eq!(&binding, artifact.binding(), "A{stage} descriptor");
        assert_eq!(key.to_bytes(), artifact.key().to_bytes(), "A{stage} key");
        if stage > 0 {
            assert!(source(stage, None).is_err(), "A{stage} missing W");
        }
        if let Some(expected) = w.get(stage) {
            let candidate = wrapper(stage, artifact.binding(), artifact.key()).unwrap();
            let (binding, key) = keygen_vk_with_binding_v2(pallas, &candidate, &w_config).unwrap();
            assert_eq!(&binding, expected.binding(), "W{stage} descriptor");
            assert_eq!(key.to_bytes(), expected.key().to_bytes(), "W{stage} key");
            let next = WKey::from_artifact(context, stage, binding, pallas.clone(), key).unwrap();
            assert!(source(0, Some(next.clone())).is_err(), "A0 extra W");
            if stage > 0 {
                assert!(
                    source(stage, Some(next.clone())).is_err(),
                    "A{stage} must reject W{stage}, its own later wrapper"
                );
            }
            previous = Some(next);
        }
    }
    for stage in [a.len(), usize::MAX] {
        assert!(source(stage, None).is_err());
        assert!(source(stage, previous.clone()).is_err());
    }
    for stage in [a.len() - 1, a.len(), usize::MAX] {
        assert!(wrapper(stage, a[0].binding(), a[0].key()).is_err());
    }
    // A wrapper must never accept an internal W profile as its source descriptor.
    assert!(wrapper(0, w[0].binding(), a[0].key()).is_err());
}
